// Centralized role-based access control. Every authorisation check goes through here.
// Replace the default in-memory policy with a real store / library (Casbin, Oso, OPA).

import type { Request, Response, NextFunction } from 'express';
import { auditLog } from './audit_log';

export type Role = string;          // e.g. 'physician', 'admin', 'patient'
export type Permission = string;    // e.g. 'patient:read', 'prescription:create', 'dsr:respond'

export interface PolicyStore {
  permissionsFor(role: Role): Permission[];
  rolesFor(actorId: string): Promise<Role[]>;
}

let store: PolicyStore | null = null;
export function setPolicyStore(p: PolicyStore): void { store = p; }

function requireStore(): PolicyStore {
  if (!store) throw new Error('secure-by-design: PolicyStore not configured.');
  return store;
}

/**
 * Check whether an actor has a permission. Returns boolean.
 * For control-flow gates, use `requirePermission(...)` which throws.
 */
export async function check(actorId: string, permission: Permission): Promise<boolean> {
  const roles = await requireStore().rolesFor(actorId);
  for (const role of roles) {
    const perms = requireStore().permissionsFor(role);
    if (perms.includes(permission) || perms.includes('*')) return true;
  }
  return false;
}

/**
 * Throw if the actor does not have the permission. Audit-logs the check either way.
 */
export async function requirePermission(actorId: string, permission: Permission): Promise<void> {
  const allowed = await check(actorId, permission);
  await auditLog.security('rbac.check', {
    actor: actorId,
    severity: allowed ? 'INFO' : 'WARN',
    outcome: allowed ? 'success' : 'denied',
    attrs: { permission },
  });
  if (!allowed) {
    const err: Error & { statusCode?: number; code?: string } = new Error(`Permission denied: ${permission}`);
    err.statusCode = 403;
    err.code = 'PERMISSION_DENIED';
    throw err;
  }
}

/**
 * Express middleware factory.
 *
 *   router.post('/patients', requires('patient:create'), createPatientHandler);
 */
export function requires(permission: Permission) {
  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const actorId = (req as Request & { user?: { id?: string } }).user?.id;
      if (!actorId) {
        res.status(401).json({ error: 'unauthenticated' });
        return;
      }
      await requirePermission(actorId, permission);
      next();
    } catch (e) {
      const err = e as Error & { statusCode?: number };
      if (err.statusCode) {
        res.status(err.statusCode).json({ error: err.message });
        return;
      }
      next(e);
    }
  };
}

/**
 * Trivial default policy store for bootstrapping. REPLACE before production.
 */
export function inMemoryPolicyStore(policy: {
  rolesByActor: Record<string, Role[]>;
  permissionsByRole: Record<Role, Permission[]>;
}): PolicyStore {
  return {
    permissionsFor: (role) => policy.permissionsByRole[role] ?? [],
    rolesFor: async (actorId) => policy.rolesByActor[actorId] ?? [],
  };
}
